mapper.select:
SELECT 

FROM favorites

    user_id = #{query.userId}
    AND is_available = 1

        AND category_id = #{searchDto.categoryId}


        AND item_type = #{searchDto.itemType}


        AND (
            title LIKE CONCAT('%', #{searchDto.keyword}, '%')
            OR content LIKE CONCAT('%', #{searchDto.keyword}, '%')
            OR note LIKE CONCAT('%', #{searchDto.keyword}, '%')
            OR sender_name LIKE CONCAT('%', #{searchDto.keyword}, '%')
            OR source_chat_name LIKE CONCAT('%', #{searchDto.keyword}, '%')
        )


        AND (

                JSON_CONTAINS(tags, JSON_QUOTE(#{tag}))

        )


        AND create_time >= #{searchDto.startTime}


        AND create_time  <= #{searchDto.endTime}





            ${searchDto.sortBy}

                ${searchDto.sortOrder}




        ORDER BY create_time DESC

