mapper.delete:
DELETE FROM favorites 
WHERE user_id = #{userId} 
AND id IN (${ids})

mapper.select:
SELECT COUNT(1) 
FROM favorites 
WHERE user_id = #{userId} 
AND item_type = #{itemType} 
AND content = #{content}
AND is_available = 1
AND deleted = 0

mapper.update:
UPDATE favorites 
SET is_available = #{isAvailable}, update_time = NOW()
WHERE id = #{id} AND user_id = #{userId}

mapper.select:
SELECT 
    DATE(create_time) as date,
    COUNT(1) as count
FROM favorites 
WHERE user_id = #{userId} 
AND is_available = 1

    AND DATE(create_time) >= #{startDate}


    AND DATE(create_time)  <= #{endDate}

GROUP BY DATE(create_time)
ORDER BY date ASC
